parameters.jsCode:
// 1. Barème lu depuis Google Sheets
const num = v => Number(String(v).replace(',', '.'));
const bareme = {};
for (const { json: r } of $input.all()) {
  const cat = String(r.categorie || '').trim().toLowerCase();
  if (!cat) continue;
  bareme[cat] = { m2: num(r.m2), u: num(r.u), forfait: num(r.forfait) };
}
if (!bareme.autre) {
  throw new Error('Barème vide ou ligne "autre" manquante : vérifier le Google Sheet');
}

// 2. Postes proposés par l'IA
const postes = $('Parser réponse IA Qwen').all();

return postes.map(({ json: p }) => {
  const cat = bareme[p.categorie] ? p.categorie : 'autre';
  let unite = p.unite;
  let qte = Number(p.quantite) || 1;
  const pu = bareme[cat][unite];
  if (!Number.isFinite(pu)) { unite = 'forfait'; qte = 1; }
  const prix = bareme[cat][unite];
  if (!Number.isFinite(prix)) {
    throw new Error('Prix invalide dans le Sheet pour : ' + cat + ' / ' + unite);
  }
  return { json: { ...p, categorie: cat, unite, quantite: qte,
    prix_unitaire: prix, total_ht: Math.round(qte * prix * 100) / 100 } };
});

const items = $input.all();

// Si l'IA a échoué en amont, on laisse passer l'erreur
if (items[0].json.erreur) return items;

const TAUX_TVA = 0.10; // 10 % : travaux de rénovation en logement ancien (modifiable)
const arrondi = n => Math.round(n * 100) / 100;

const lignes = items.map(i => ({
  categorie: i.json.categorie,
  description: i.json.description,
  quantite: i.json.quantite,
  unite: i.json.unite,
  prix_unitaire: i.json.prix_unitaire,
  total_ht: i.json.total_ht
}));

const total_ht = arrondi(lignes.reduce((s, l) => s + l.total_ht, 0));
const montant_tva = arrondi(total_ht * TAUX_TVA);
const total_ttc = arrondi(total_ht + montant_tva);

const date = new Date();
const numero = 'DEV-' + date.toISOString().slice(0, 10).replace(/-/g, '') + '-' +
               String(Math.floor(Math.random() * 900) + 100);

return [{
  json: {
    numero,
    date: date.toLocaleDateString('fr-FR'),
    client: items[0].json.client,
    email: items[0].json.email,
    lignes,
    total_ht,
    taux_tva: TAUX_TVA * 100,
    montant_tva,
    total_ttc
  }
}];

const d = $input.first().json;

// Si l'IA a échoué en amont, on laisse passer l'erreur
if (d.erreur) return $input.all();

const esc = s => String(s).replace(/[&<>"]/g, c =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const eur = n => n.toLocaleString('fr-FR', { minimumFractionDigits: 2 }) + ' €';

const rows = d.lignes.map(l => `
  <tr>
    <td>${esc(l.categorie)}</td>
    <td>${esc(l.description)}</td>
    <td class="r">${l.quantite} ${esc(l.unite)}</td>
    <td class="r">${eur(l.prix_unitaire)}</td>
    <td class="r">${eur(l.total_ht)}</td>
  </tr>`).join('');

const html = `<!DOCTYPE html>
<html lang="fr"><head><meta charset="utf-8"><title>${d.numero}</title>
<style>
  body{font-family:Arial,sans-serif;max-width:800px;margin:30px auto;color:#222}
  h1{margin-bottom:0} .tag{color:#b45309;font-weight:bold}
  table{width:100%;border-collapse:collapse;margin-top:20px}
  th,td{border:1px solid #ddd;padding:8px;font-size:14px}
  th{background:#f3f4f6;text-align:left} .r{text-align:right}
  .tot td{border:none;padding:4px 8px} .tot .big{font-size:16px;font-weight:bold}
  small{color:#666}
</style></head><body>
  <h1>Pré-devis travaux</h1>
  <p class="tag">Document indicatif, à valider par notre équipe</p>
  <p><b>N° :</b> ${d.numero}<br><b>Date :</b> ${d.date}<br>
  <b>Client :</b> ${esc(d.client)} (${esc(d.email)})</p>
  <table>
    <tr><th>Catégorie</th><th>Description</th><th class="r">Quantité</th>
        <th class="r">PU HT</th><th class="r">Total HT</th></tr>
    ${rows}
  </table>
  <table class="tot" style="width:320px;margin-left:auto">
    <tr><td>Total HT</td><td class="r">${eur(d.total_ht)}</td></tr>
    <tr><td>TVA (${d.taux_tva} %)</td><td class="r">${eur(d.montant_tva)}</td></tr>
    <tr class="big"><td class="big">Total TTC</td><td class="r big">${eur(d.total_ttc)}</td></tr>
  </table>
  <p><small>Estimation générée automatiquement à partir de la description du chantier. Prix fictifs (démo).</small></p>
</body></html>`;

const binary = await this.helpers.prepareBinaryData(
  Buffer.from(html, 'utf-8'), d.numero + '.html', 'text/html');

return [{ json: { ...d, html }, binary: { data: binary } }];

const raw = $input.first().json.choices[0].message.content;
const form = $('On form submission').first().json;

let data;
try {
  data = JSON.parse(raw.replace(/```json|```/g, '').trim());
  if (!Array.isArray(data.postes) || data.postes.length === 0) {
    throw new Error('Liste "postes" absente ou vide');
  }
} catch (e) {
  return [{ json: { erreur: true, message: e.message, brut: raw } }];
}

return data.postes.map(p => ({
  json: {
    ...p,
    client: form['Nom du client'],
    email: form['Email']
  }
}));
